// Pick 6-10 random send times between 8am and 6pm (480-1080 min from midnight)
// Each item = one send batch. batchWaitMinutes = minutes to wait from midnight.
var count = 6 + Math.floor(Math.random() * 5); // 6-10
var times = [];
for (var i = 0; i < count; i++) {
  times.push(480 + Math.floor(Math.random() * 601)); // 8am-6pm
}
times.sort(function(a,b){return a-b;});
var results = [];
for (var j = 0; j < times.length; j++) {
  var waitMins = j === 0 ? times[0] : times[j] - times[j-1];
  results.push({ json: { batchIndex: j + 1, batchWaitMinutes: waitMins, totalBatches: count } });
}
return results;

