  var recipientName = randomNames[Math.floor(Math.random() * randomNames.length)];
  var delayMinutes = Math.floor(Math.random() * 45);
  results.push({ json: { senderSlot: sender.slot, senderFrom: sender.from, senderName: sender.name, receivers: [receiver], topic: topic, recipientName: recipientName, delayMinutes: delayMinutes } });
}
return results;

var results = [];
for (var i = 0; i < $input.all().length; i++) {
  var item = $input.all()[i].json;
  var response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.deepseek.com/chat/completions',
    headers: {
      'Authorization': 'Bearer YOUR_TOKEN_HERE',
      'Content-Type': 'application/json'
    },
    body: {
      model: 'deepseek-chat',
      messages: [
        {
          role: 'system',
          content: 'You are an office admin assistant writing a short internal business email. Write a realistic, natural-sounding email between 10 and 60 words. Include a subject line on the first line starting with "Subject: ", then a blank line, then the email body. Use the sender name and recipient name provided. Never use placeholders like [Name] or [Recipient] — always use the actual names given. Do not add any explanation or extra text outside the email.'
        },
        {
          role: 'user',
          content: 'Topic: ' + item.topic + '. Sender name: ' + item.senderName + '. Recipient name: ' + item.recipientName + '. Write the email now. Address the recipient by their first name (' + item.recipientName + ') in the greeting. Do not use placeholders like [Name].'
        }
      ],
      max_tokens: 150
    },
    json: true
  });
  var raw = (response.choices && response.choices[0] && response.choices[0].message && response.choices[0].message.content) ? response.choices[0].message.content.trim() : '';
  var lines = raw.split('\n');
  var subjectLine = lines.find(function(l) { return l.toLowerCase().startsWith('subject:'); }) || 'Subject: Quick update';
  var subject = subjectLine.replace(/^subject:\s*/i, '').trim();
  var bodyLines = lines.filter(function(l) { return !l.toLowerCase().startsWith('subject:'); });
  var body = bodyLines.join('\n').trim();
  results.push({ json: Object.assign({}, item, { subject: subject, emailBody: body }) });
}
return results;

